package com.ofss.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime;
@Entity @Table(name="PPC_SIMULATED_PAYMENTS",uniqueConstraints=@UniqueConstraint(name="UK_PPC_PAYMENT",columnNames="PAYMENT_ID")) public class SimulatedPayment {@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="sim_payment_seq") @SequenceGenerator(name="sim_payment_seq",sequenceName="PPC_SIMULATED_PAYMENTS_SEQ",allocationSize=50) @Column(name="PROCESSING_ID") private Long id; @Column(name="PAYMENT_ID",nullable=false,length=100) private String paymentId; @Column(name="SUPPLIER_ID",nullable=false) private Long supplierId; @Column(name="AMOUNT",nullable=false,precision=15,scale=2) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(name="STATUS",nullable=false) private ProcessingStatus status; @Column(name="REASON",length=500) private String reason; @Column(name="PROCESSED_AT",nullable=false) private OffsetDateTime processedAt; @PrePersist void init(){if(processedAt==null)processedAt=OffsetDateTime.now();} public String getPaymentId(){return paymentId;} public void setPaymentId(String v){paymentId=v;} public void setSupplierId(Long v){supplierId=v;} public void setAmount(BigDecimal v){amount=v;} public ProcessingStatus getStatus(){return status;} public void setStatus(ProcessingStatus v){status=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public OffsetDateTime getProcessedAt(){return processedAt;}}
